async function scheduleUserPushes(userId) {
  const user = await getUser(userId);
  const context = await computeUserContext(user);

  // Morning greeting
  schedulePush({
    userId,
    time: '08:00',
    timezone: user.timezone,
    message: pickTemplate('morning_greetings', context),
    category: 'content_hook'
  });

  // Full moon special
  if (context.days_to_full_moon === 0) {
    schedulePush({
      userId,
      time: '19:00',
      message: pickTemplate('full_moon', context),
      category: 'event'
    });
  }

  // Personalized zodiac message
  schedulePush({
    userId,
    time: '10:30',
    message: pickTemplate('zodiac_specific', context)[user.sun_sign],
    category: 'insight'
  });
}
